using System;
using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace LakskongenSim.Advisor
{
    /// <summary>
    /// Represents a single recommendation generated by the Intelligent Advisor System.
    /// Combines environmental, biological, and economic data into actionable advice.
    /// </summary>
    public class Recommendation
    {
        /// <summary>Unique identifier for this recommendation.</summary>
        public string Id { get; set; } = Guid.NewGuid().ToString();

        /// <summary>Timestamp when the recommendation was generated.</summary>
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

        /// <summary>Simulation day when the recommendation was generated.</summary>
        public int SimulationDay { get; set; }

        /// <summary>Type of recommendation (harvest, feeding, pen management, etc.).</summary>
        public RecommendationType Type { get; set; }

        /// <summary>Category for grouping similar recommendations.</summary>
        public RecommendationCategory Category { get; set; }

        /// <summary>Short, actionable title for the recommendation.</summary>
        public string Title { get; set; } = "";

        /// <summary>Detailed description of the recommendation.</summary>
        public string Description { get; set; } = "";

        /// <summary>Specific action the player should take.</summary>
        public string RecommendedAction { get; set; } = "";

        /// <summary>Target zone, site, or pen this recommendation applies to (if applicable).</summary>
        public string? TargetZoneId { get; set; }

        /// <summary>Target site ID (if applicable).</summary>
        public string? TargetSiteId { get; set; }

        /// <summary>Target population/pen ID (if applicable).</summary>
        public string? TargetPopulationId { get; set; }

        // ─── Scoring ─────────────────────────────────────────────────────────

        /// <summary>Confidence level (0.0-1.0) based on data quality and model certainty.</summary>
        public double ConfidenceLevel { get; set; }

        /// <summary>Urgency rating (1-5, 5 being most urgent).</summary>
        public int UrgencyRating { get; set; }

        /// <summary>Expected financial impact in NOK (positive = gain, negative = cost/loss).</summary>
        public decimal ExpectedImpactNOK { get; set; }

        /// <summary>Time horizon for the recommendation (immediate, short-term, long-term).</summary>
        public TimeHorizon TimeHorizon { get; set; }

        /// <summary>Estimated probability of success/positive outcome.</summary>
        public double SuccessProbability { get; set; }

        // ─── Supporting Data ─────────────────────────────────────────────────

        /// <summary>Environmental factors that influenced this recommendation.</summary>
        public EnvironmentalFactors EnvironmentalContext { get; set; } = new();

        /// <summary>Biological factors that influenced this recommendation.</summary>
        public BiologicalFactors BiologicalContext { get; set; } = new();

        /// <summary>Economic/market factors that influenced this recommendation.</summary>
        public EconomicFactors EconomicContext { get; set; } = new();

        /// <summary>Risk factors considered in this recommendation.</summary>
        public RiskFactors RiskContext { get; set; } = new();

        // ─── Tracking ────────────────────────────────────────────────────────

        /// <summary>Whether the player has seen this recommendation.</summary>
        public bool IsRead { get; set; } = false;

        /// <summary>Whether the player has dismissed this recommendation.</summary>
        public bool IsDismissed { get; set; } = false;

        /// <summary>Whether the player acted on this recommendation.</summary>
        public bool WasFollowed { get; set; } = false;

        /// <summary>Timestamp when the player acted on or dismissed the recommendation.</summary>
        public DateTime? ResolvedAt { get; set; }

        /// <summary>Actual outcome if the recommendation was followed.</summary>
        public RecommendationOutcome? Outcome { get; set; }

        /// <summary>Feedback score (-1 to 1) based on actual vs expected outcome.</summary>
        public double? OutcomeFeedbackScore { get; set; }

        /// <summary>Related alert IDs (if this recommendation was triggered by alerts).</summary>
        public List<string> RelatedAlertIds { get; set; } = new();

        /// <summary>Narrative/story text for integration with AI storyteller.</summary>
        public string? NarrativeText { get; set; }

        /// <summary>Gets a display-friendly urgency label.</summary>
        [JsonIgnore]
        public string UrgencyLabel => UrgencyRating switch
        {
            5 => "🔴 Kritisk",
            4 => "🟠 Høy",
            3 => "🟡 Middels",
            2 => "🔵 Lav",
            _ => "⚪ Informativ"
        };

        /// <summary>Gets a display-friendly confidence label.</summary>
        [JsonIgnore]
        public string ConfidenceLabel => ConfidenceLevel switch
        {
            >= 0.9 => "Svært høy",
            >= 0.75 => "Høy",
            >= 0.6 => "Middels",
            >= 0.4 => "Lav",
            _ => "Usikker"
        };

        /// <summary>Gets the impact formatted as currency.</summary>
        [JsonIgnore]
        public string FormattedImpact => ExpectedImpactNOK >= 0
            ? $"+{ExpectedImpactNOK:N0} NOK"
            : $"{ExpectedImpactNOK:N0} NOK";
    }

    /// <summary>Types of recommendations the advisor can generate.</summary>
    public enum RecommendationType
    {
        HarvestTiming,
        FeedingAdjustment,
        PenManagement,
        MarketTiming,
        RiskMitigation,
        ExpansionOpportunity,
        CostOptimization,
        SustainabilityImprovement,
        DiseasePrevention,
        QualityImprovement,
        LogisticsOptimization,
        ResearchPriority,
        RegulatoryCompliance
    }

    /// <summary>Categories for grouping recommendations.</summary>
    public enum RecommendationCategory
    {
        Operations,
        Financial,
        Biological,
        Environmental,
        Strategic,
        Compliance,
        Emergency
    }

    /// <summary>Time horizons for recommendations.</summary>
    public enum TimeHorizon
    {
        Immediate,      // Act within 24 hours
        ShortTerm,      // Act within 1-7 days
        MediumTerm,     // Act within 1-4 weeks
        LongTerm        // Strategic, act within months
    }

    /// <summary>Environmental factors considered in recommendations.</summary>
    public class EnvironmentalFactors
    {
        public double Temperature { get; set; }
        public double OxygenLevel { get; set; }
        public double CurrentSpeed { get; set; }
        public double TemperatureStressIndex { get; set; }
        public double OxygenStressIndex { get; set; }
        public double EnvironmentalQualityScore { get; set; }
        public bool AlgalBloomRisk { get; set; }
        public double ForecastedTemperature { get; set; }
        public double ForecastedOxygen { get; set; }
        public string Season { get; set; } = "";
        public int DaysUntilAdverseConditions { get; set; } = -1;
    }

    /// <summary>Biological factors considered in recommendations.</summary>
    public class BiologicalFactors
    {
        public double AverageWeightKg { get; set; }
        public int FishCount { get; set; }
        public double TotalBiomassKg { get; set; }
        public int DaysInSea { get; set; }
        public double MortalityRate { get; set; }
        public double SeaLiceCount { get; set; }
        public double FeedConversionRatio { get; set; }
        public double GrowthRate { get; set; }
        public double StockingDensity { get; set; }
        public double HealthScore { get; set; }
        public string? LifeStage { get; set; }
        public double DaysToOptimalHarvest { get; set; }
        public double OptimalHarvestWeight { get; set; } = 4.5; // kg
    }

    /// <summary>Economic/market factors considered in recommendations.</summary>
    public class EconomicFactors
    {
        public decimal CurrentPricePerKg { get; set; }
        public decimal ForecastedPricePerKg { get; set; }
        public decimal PriceTrend { get; set; } // 1.0 = stable, >1 = rising, <1 = falling
        public decimal FeedCostPerKg { get; set; }
        public decimal OperationalCostPerDay { get; set; }
        public decimal MarginPerKg { get; set; }
        public double MarketDemandIndex { get; set; }
        public double MarketSupplyIndex { get; set; }
        public decimal CashPosition { get; set; }
        public decimal DebtToEquityRatio { get; set; }
        public decimal LongTermMean { get; set; }
    }

    /// <summary>Risk factors considered in recommendations.</summary>
    public class RiskFactors
    {
        public double MortalityRisk { get; set; }
        public double DiseaseOutbreakRisk { get; set; }
        public double EnvironmentalRisk { get; set; }
        public double MarketVolatilityRisk { get; set; }
        public double RegulatoryRisk { get; set; }
        public double FinancialRisk { get; set; }
        public List<string> ActiveRisks { get; set; } = new();
        public double OverallRiskScore { get; set; }
    }

    /// <summary>Tracks the actual outcome of a followed recommendation.</summary>
    public class RecommendationOutcome
    {
        public DateTime RecordedAt { get; set; } = DateTime.UtcNow;
        public int SimulationDay { get; set; }
        public decimal ActualImpactNOK { get; set; }
        public double ActualMortalityRate { get; set; }
        public decimal ActualPricePerKg { get; set; }
        public double ActualGrowthRate { get; set; }
        public bool WasSuccessful { get; set; }
        public string? Notes { get; set; }
    }
}
